          if (!pending.size) {
            await saveHeld()
            return
          }
        }
        for (const [id, line] of current) if (!seen.has(id) && (!observed.has(id) || pending.has(id))) {
          pending.set(id, { ...line, checksAt: pending.get(id)?.checksAt ?? line.checksAt })
        }
